contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 aprLow, uint256 aprHigh, uint256 tenor) public {
        InitializeRiskConfigParams memory rc = c.riskConfig();
        uint256 minTenor = rc.minTenor;
        uint256 maxTenor = rc.maxTenor;
        require(minTenor < maxTenor);
        require(minTenor <= tenor && tenor <= maxTenor);
        require(aprLow <= type(int256).max);
        require(aprHigh <= type(int256).max);

        uint256[] memory tenors = new uint256[](2);
        tenors[0] = minTenor;
        tenors[1] = maxTenor;
        int256[] memory aprs = new int256[](2);
        aprs[0] = int256(aprLow);
        aprs[1] = int256(aprHigh);
        uint256[] memory mults = new uint256[](2);
        mults[0] = 0;
        mults[1] = 0;

        SellCreditLimitParams memory params;
        params.curveRelativeTime.tenors = tenors;
        params.curveRelativeTime.aprs = aprs;
        params.curveRelativeTime.marketRateMultipliers = mults;
        c.sellCreditLimit(params);

        uint256 aprAtMin = c.getBorrowOfferAPR(address(this), minTenor);
        uint256 aprAtMax = c.getBorrowOfferAPR(address(this), maxTenor);
        uint256 aprAtTenor = c.getBorrowOfferAPR(address(this), tenor);

        uint256 lower = aprLow < aprHigh ? aprLow : aprHigh;
        uint256 upper = aprLow > aprHigh ? aprLow : aprHigh;
        assert(
            aprAtMin == aprLow &&
            aprAtMax == aprHigh &&
            aprAtTenor >= lower &&
            aprAtTenor <= upper
        );
    }
    receive() external payable {}
}

