contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 value) public {
        // initialize the fresh protocol with a valid fixture so that this contract owns all roles
        InitializeFeeConfigParams memory f = InitializeFeeConfigParams({
            swapFeeAPR: 0,
            fragmentationFee: 0,
            liquidationRewardPercent: 0,
            overdueCollateralProtocolPercent: 0,
            collateralProtocolPercent: 0,
            feeRecipient: address(0x1)
        });
        InitializeRiskConfigParams memory r = InitializeRiskConfigParams({
            crOpening: 1.5e18,
            crLiquidation: 1.2e18,
            minimumCreditBorrowAToken: 1e6,
            borrowATokenCap: type(uint256).max,
            minTenor: 1 days,
            maxTenor: 90 days
        });
        InitializeOracleParams memory o = InitializeOracleParams({
            priceFeed: address(0x2),
            variablePoolBorrowRateStaleRateInterval: 1 hours
        });
        InitializeDataParams memory d = InitializeDataParams({
            weth: address(0x3),
            underlyingCollateralToken: address(0x4),
            underlyingBorrowToken: address(0x5),
            variablePool: address(0x6)
        });

        c.initialize(address(this), f, r, o, d);

        uint256 crLiquidationBefore = c.riskConfig().crLiquidation;

        bool reverted;
        try c.updateConfig(UpdateConfigParams({key: "crOpening", value: value})) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 crOpeningAfter = c.riskConfig().crOpening;

        // General rule: the update is accepted exactly when value is at least PERCENT
        // and strictly greater than the liquidation collateral ratio; when accepted,
        // crOpening is set to exactly value.
        assert(
            (value >= PERCENT && value > crLiquidationBefore)
                ? (!reverted && crOpeningAfter == value)
                : reverted
        );
    }
}

