contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 y, uint256 x, uint256 t1, uint256 t2) public {
        require(y <= x, "cash must be non-decreasing");
        require(t1 > 0, "tenor must be positive");
        require(t1 <= t2, "tenors must be non-decreasing");

        // Both are read-only view calls, safe to invoke and compare
        uint256 feeSmall = c.getSwapFee(y, t1);
        uint256 feeLarge = c.getSwapFee(x, t2);

        // General rule: swap fee is monotonically non-decreasing in cash and tenor
        assert(feeLarge >= feeSmall);
    }
}
